'use strict';
const $=id=>document.getElementById(id),dayKey=()=>new Date().toLocaleDateString('en-CA');
const defaults={coins:0,best:0,words:0,stars:{},owned:['arcade'],theme:'arcade',dailyWins:[],claimed:[],sound:true};
let profile,mode='classic',s,selection=[],positions=[],drag=null,page='home',lastFocus;
try{profile={...defaults,...JSON.parse(localStorage.getItem('bloom-profile-v4')||'{}')};const old=JSON.parse(localStorage.getItem('bloom-prefs')||'{}');profile.best=Math.max(profile.best,old.best||0)}catch{profile={...defaults}}
const worlds=[{name:'Candy Coast',icon:'🍭',desc:'Your sweet beginning',color:'pink'},{name:'Jungle Jam',icon:'🌴',desc:'Let your vocabulary go wild',color:'green'},{name:'Cosmic Carnival',icon:'🪐',desc:'Words from another world',color:'purple'}];
function persist(){try{localStorage.setItem('bloom-profile-v4',JSON.stringify(profile));if(s)localStorage.setItem('bloom-run-v4-'+mode,JSON.stringify(s))}catch{}}
function fresh(m,id=1){mode=m;s={rng:m==='daily'?hash(dayKey()):m==='adventure'?hash('bloom-adventure-'+id):Math.floor(Math.random()*4294967295),letters:[],found:[],score:0,lives:3,streak:0,stageCount:0,hints:3,hint:null,round:1,date:dayKey(),over:false,id,words:0,target:m==='daily'?6:m==='adventure'?Math.min(8,3+Math.floor((id-1)/5)):10};s.letters=newLetters(m==='classic'?profile.lastStart||'':'');if(m==='classic')profile.lastStart=signature(s.letters);persist()}
function loadRun(m,id){mode=m;let old;try{old=JSON.parse(localStorage.getItem('bloom-run-v4-'+m));if(!old&&m==='classic'){const legacy=JSON.parse(localStorage.getItem('letter-bloom-v2-classic'));if(legacy&&Array.isArray(legacy.letters)&&wordGroups.has(signature(legacy.letters)))old={...legacy,id:1,words:legacy.found.length,target:10,hint:null}}}catch{}if(old&&!old.over&&(m!=='daily'||old.date===dayKey())&&(m!=='adventure'||old.id===id))s=old;else fresh(m,id);showGame()}
function starsTotal(){return Object.values(profile.stars).reduce((a,b)=>a+b,0)}
function unlocked(){for(let i=1;i<=30;i++)if(!profile.stars[i])return i;return 30}
function chrome(p){page=p;drag=null;selection=[];document.body.dataset.theme=profile.theme;$('app').classList.toggle('playing',p==='game');document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('screen').className=p;$('screen').scrollTop=0}
function home(){chrome('home');$('screen').innerHTML=`<div class="wallet"><span>★ ${starsTotal()} stars</span><span>🪙 ${profile.coins}</span></div><section class="hero"><div class="spark s1">✦</div><div class="spark s2">✦</div><div class="hero-title">LETTER<br><strong>BLOOM</strong></div><div class="mascot-scene" aria-hidden="true"><span class="mini-tile t1">A</span><div class="mascot"><div class="eyes">● ●</div><div class="smile"></div><b>B</b></div><span class="mini-tile t2">Z</span><span class="island"></span></div><p>Little letters. BIG adventures.</p></section><button class="mode-card adventure-card" id="go-adventure"><span class="mode-icon">🚀</span><span><small>EXPLORE 30 LEVELS</small><b>Adventure</b><em>Next stop: level ${unlocked()}</em></span><strong>➜</strong></button><div class="mode-grid"><button class="mode-card classic-card" id="go-classic"><span class="mode-icon">⚡</span><b>Classic</b><em>Endless word rush</em><span class="pill">PLAY →</span></button><button class="mode-card daily-card" id="go-daily"><span class="mode-icon">☀</span><b>Daily Challenge</b><em>A fresh puzzle daily</em><span class="pill">${profile.dailyWins.includes(dayKey())?'✓ COMPLETED':'PLAY →'}</span></button></div><button class="quest-teaser" id="go-quests"><span>🎁</span><div><b>Your next reward is waiting</b><small>Complete goals • earn coins • unlock looks</small></div><b>›</b></button><p class="home-best">🏆 PERSONAL BEST <b>${profile.best}</b></p>`;$('go-adventure').onclick=adventure;$('go-classic').onclick=()=>loadRun('classic');$('go-daily').onclick=()=>loadRun('daily');$('go-quests').onclick=rewards}
function adventure(){chrome('adventure');$('screen').innerHTML=`<div class="page-title"><small>YOUR WORD JOURNEY</small><h1>Adventure</h1><p>30 stops. Three worlds. One big adventure.</p></div><div class="map-summary">★ ${starsTotal()} / 90 stars <span>Level ${unlocked()} unlocked</span></div>`+worlds.map((w,wi)=>`<section class="world ${w.color}"><div class="world-head"><span>${w.icon}</span><div><small>WORLD 0${wi+1}</small><h2>${w.name}</h2><p>${w.desc}</p></div></div><div class="level-map">${Array.from({length:10},(_,j)=>{const id=wi*10+j+1,locked=id>unlocked(),star=profile.stars[id]||0;return `<button class="level-node ${star?'done':''} ${id===unlocked()?'current':''}" data-level="${id}" ${locked?'disabled':''} aria-label="Level ${id}${locked?', locked':', '+star+' stars'}"><b>${locked?'🔒':id}</b><span>${star?'★'.repeat(star)+'☆'.repeat(3-star):locked?'':'PLAY'}</span></button>`}).join('')}</div></section>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>loadRun('adventure',Number(b.dataset.level)))}
const quests=[{id:'first',name:'First bloom',desc:'Find 5 words',goal:5,value:()=>profile.words,reward:30,icon:'🌱'},{id:'explorer',name:'Trailblazer',desc:'Complete 5 adventure levels',goal:5,value:()=>Object.keys(profile.stars).length,reward:60,icon:'🧭'},{id:'wordsmith',name:'Word wizard',desc:'Find 50 words',goal:50,value:()=>profile.words,reward:100,icon:'🪄'},{id:'starlight',name:'Star collector',desc:'Collect 20 adventure stars',goal:20,value:starsTotal,reward:120,icon:'🌟'},{id:'daily',name:'Sun chaser',desc:'Finish a daily challenge',goal:1,value:()=>profile.dailyWins.length,reward:50,icon:'☀'}];
function rewards(){chrome('rewards');$('screen').innerHTML=`<div class="page-title"><small>GOOD WORDS. GREAT REWARDS.</small><h1>Your treasure</h1></div><div class="treasure"><span>🪙</span><b>${profile.coins}</b><small>COINS EARNED BY PLAYING</small></div><h2 class="section-title">Missions</h2><div class="quests">${quests.map(q=>{const v=Math.min(q.goal,q.value()),claimed=profile.claimed.includes(q.id);return `<div class="quest"><span>${q.icon}</span><div><b>${q.name}</b><small>${q.desc} · ${v}/${q.goal}</small><div class="track"><i style="width:${v/q.goal*100}%"></i></div></div><button data-claim="${q.id}" ${claimed||v<q.goal?'disabled':''}>${claimed?'✓':v>=q.goal?'Claim':'🪙 '+q.reward}</button></div>`}).join('')}</div><h2 class="section-title">Make it yours</h2><div class="theme-shop">${[{id:'arcade',name:'Pop Arcade',icon:'🎮',cost:0},{id:'candy',name:'Candy Pop',icon:'🍬',cost:80},{id:'cosmic',name:'Cosmic Glow',icon:'🌌',cost:160}].map(t=>`<button class="skin ${t.id}" data-skin="${t.id}" data-cost="${t.cost}"><span>${t.icon}</span><b>${t.name}</b><small>${profile.theme===t.id?'✓ Equipped':profile.owned.includes(t.id)?'Equip':'🪙 '+t.cost}</small></button>`).join('')}</div><p class="footnote">Progress saves on this device. No purchases or ads.</p>`;document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{const q=quests.find(q=>q.id===b.dataset.claim);if(!profile.claimed.includes(q.id)&&q.value()>=q.goal){profile.claimed.push(q.id);profile.coins+=q.reward;persist();rewards();celebrate()}});document.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{const id=b.dataset.skin,cost=Number(b.dataset.cost);if(!profile.owned.includes(id)){if(profile.coins<cost){dialog('Keep blooming!',`You need ${cost-profile.coins} more coins. Find words and complete missions to earn them.`,[{text:'Got it',action:closeDialog}]);return}profile.coins-=cost;profile.owned.push(id)}profile.theme=id;persist();rewards()})}
function showGame(){chrome('game');$('screen').innerHTML=`<div class="game-top"><span id="level"></span><span id="hearts" aria-live="polite"></span></div><div class="score-row"><div><small>SCORE</small><b id="score"></b></div><div><small id="mode-label"></small><b id="combo"></b></div></div><div class="goal-panel"><div><b id="required"></b><span id="progress-label"></span></div><div class="track"><i id="bar"></i></div><small id="next"></small></div><div id="hint-clue" class="hint-clue hidden" aria-live="polite"></div><div class="word-panel"><span id="preview"></span><button id="clear" aria-label="Clear selected letters">×</button></div><div id="message" role="status">Use every tile. Trace back to undo.</div><div class="wheel-space"><div id="wheel"><svg aria-hidden="true"><polyline id="path" points=""/><circle id="pointer-dot" r="7"/></svg><div class="wheel-center">✦</div></div></div><div class="game-actions"><button id="shuffle">⤨<small>Shuffle</small></button><button id="submit">Check word ✓</button><button id="hint">💡<small>Hint</small></button></div><div class="game-bottom"><button id="found">▦ Words <span id="count"></span></button><button id="restart">↻ Restart</button></div>`;$('clear').onclick=clear;$('submit').onclick=submit;$('shuffle').onclick=shuffle;$('hint').onclick=hint;$('found').onclick=()=>dialog('Your word collection',s.found.length?s.found.map(w=>`<span class="chip">${w.toUpperCase()}</span>`).join(''):'Your first word is waiting!',[{text:'Keep playing',action:closeDialog}]);$('restart').onclick=()=>dialog('Start a fresh run?','Your saved run will restart. Coins, stars and unlocks stay yours.',[{text:'Restart',action:()=>{fresh(mode,s.id);closeDialog();showGame()}},{text:'Keep playing',action:closeDialog}]);const w=$('wheel');w.addEventListener('pointerdown',pointerStart);w.addEventListener('pointermove',pointerMove);w.addEventListener('pointerup',pointerEnd);w.addEventListener('pointercancel',pointerCancel);w.addEventListener('lostpointercapture',pointerCancel);render()}
function render(){if(page!=='game')return;$('level').textContent=mode==='adventure'?`⚑ LEVEL ${s.id}`:mode==='daily'?'☀ DAILY CHALLENGE':`⚡ CLASSIC · ROUND ${s.round}`;$('hearts').textContent='♥'.repeat(s.lives)+'♡'.repeat(3-s.lives);$('hearts').setAttribute('aria-label',s.lives+' lives remaining');$('score').textContent=s.score;$('mode-label').textContent='WORD STREAK';$('combo').textContent=s.streak>=3?'🔥 '+s.streak+' · ×'+Math.min(3,1+Math.floor(s.streak/3)):s.streak+' in a row';$('required').textContent=s.letters.length+'-letter words';$('progress-label').textContent=s.stageCount+' / '+quota();$('bar').style.width=s.stageCount/quota()*100+'%';$('next').textContent=s.letters.length===s.target?'Finish this goal to win!':s.letters.length===9?'Next: a fresh set of 3 letters':`Next: unlock letter ${s.letters.length+1}`;$('count').textContent=s.found.length;$('shuffle').disabled=s.letters.length<4||s.over;$('shuffle').innerHTML='⤨<small>'+(s.letters.length<4?'At 4 tiles':'Shuffle')+'</small>';$('hint').disabled=(mode==='classic'&&s.letters.length<5)||s.hints===0||s.over;$('hint').innerHTML='💡<small>'+(mode==='classic'&&s.letters.length<5?'At 5 tiles':s.hints+' '+(s.hints===1?'hint':'hints'))+'</small>';drawWheel();persist()}
function drawWheel(){if(page!=='game')return;const w=$('wheel');w.querySelectorAll('.letter').forEach(b=>b.remove());const size=Math.min(w.clientWidth,w.clientHeight),r=size*.36;positions=s.letters.map((l,i)=>({x:w.clientWidth/2+Math.cos(-Math.PI/2+i*Math.PI*2/s.letters.length)*r,y:w.clientHeight/2+Math.sin(-Math.PI/2+i*Math.PI*2/s.letters.length)*r}));const hinted=hintTiles();s.letters.forEach((l,i)=>{const b=document.createElement('button');b.className='letter tile-'+i%5;b.textContent=l;b.dataset.index=i;b.style.left=positions[i].x+'px';b.style.top=positions[i].y+'px';const d=Math.min(65,Math.max(32,2*r*Math.sin(Math.PI/s.letters.length)-8));b.style.width=d+'px';b.style.height=d+'px';b.style.fontSize=d*.48+'px';b.setAttribute('aria-label','Letter '+l+' tile '+(i+1));b.classList.toggle('hinted',hinted.includes(i));if(hinted.includes(i))b.dataset.hint=hinted.indexOf(i)+1;b.onclick=e=>{if(e.detail===0){selection=BloomTrace.follow(selection,i,true);drawSelection()}};w.append(b)});$('hint-clue').classList.toggle('hidden',!s.hint);$('hint-clue').textContent=s.hint?'💡 '+[...s.hint.word].map((c,i)=>i<s.hint.revealed?c.toUpperCase():'＿').join(' '):'';drawSelection()}
function drawSelection(){if(page!=='game')return;document.querySelectorAll('.letter').forEach((b,i)=>{b.classList.toggle('selected',selection.includes(i));b.setAttribute('aria-pressed',selection.includes(i))});$('preview').textContent=selection.map(i=>s.letters[i]).join('')||'CONNECT THE LETTERS';$('preview').classList.toggle('empty',!selection.length);$('submit').disabled=selection.length!==s.letters.length||s.over;$('path').setAttribute('points',BloomTrace.points(selection,positions,drag?.cursor));$('pointer-dot').style.display=drag&&selection.length?'':'none';if(drag){$('pointer-dot').setAttribute('cx',drag.cursor.x);$('pointer-dot').setAttribute('cy',drag.cursor.y)}}
function clear(){selection=[];drawSelection()}
function message(t){if($('message'))$('message').textContent=t}
function select(i){selection=BloomTrace.follow(selection,i);drawSelection()}
function submit(){if(s.over)return;const word=selection.map(i=>s.letters[i]).join('').toLowerCase();clear();if(word.length!==s.letters.length){message('Use every tile. No life lost.');return}if(s.found.includes(word)){message('Already found! Try another word.');return}if(!WORDS.has(word)){s.lives--;s.streak=0;render();sound(false);message('Not in the dictionary. Try again!');$('wheel').classList.add('shake');setTimeout(()=>$('wheel')?.classList.remove('shake'),400);if(!s.lives){s.over=true;persist();finish(false)}return}s.score+=word.length*10*Math.min(3,1+Math.floor(s.streak/3));s.streak++;s.words++;s.found.push(word);s.stageCount++;profile.words++;profile.coins+=2;profile.best=Math.max(profile.best,s.score);if(s.hint?.word===word)s.hint=null;let msg=word.toUpperCase()+'! +2 coins ✨';sound(true);if(s.stageCount>=quota()){if(s.letters.length===s.target){s.over=true;persist();finish(true);return}if(s.letters.length<9){const l=addLetter();msg='New letter: '+l+'! Now use all '+s.letters.length+' tiles.'}else{s.round++;s.letters=newLetters(s.letters);s.found=[];s.stageCount=0;s.hints=3;s.hint=null;msg='New round! Fresh letters, same score.'}celebrate()}render();message(msg);if(navigator.vibrate)navigator.vibrate(15)}
function finish(won){let reward=0,stars=s.lives;if(won&&mode==='adventure'){const old=profile.stars[s.id]||0;profile.stars[s.id]=Math.max(old,stars);reward=old?0:20+s.id*2;profile.coins+=reward}if(won&&mode==='daily'&&!profile.dailyWins.includes(dayKey())){profile.dailyWins.push(dayKey());reward=60;profile.coins+=reward}persist();if(won)celebrate();dialog(won?'You bloomed!':'Keep your chin up!',`<div class="win-stars">${won?'★'.repeat(stars)+'☆'.repeat(3-stars):'💜'}</div><div class="result-score">${s.score}</div><p>${s.words} words found${reward?' · +'+reward+' coins':''}</p>${won?'<p>Another adventure is waiting.</p>':'<p>You could have tried: '+possible().slice(0,3).join(', ').toUpperCase()+'</p>'}`,[{text:won&&mode==='adventure'&&s.id<30?'Next level →':'Play again',action:()=>{const id=won&&mode==='adventure'?Math.min(30,s.id+1):s.id;fresh(mode,id);closeDialog();showGame()}},{text:mode==='adventure'?'Back to map':'Back home',action:()=>{closeDialog();mode==='adventure'?adventure():home()}}])}
function shuffle(){if(s.letters.length<4||s.over)return;for(let i=s.letters.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[s.letters[i],s.letters[j]]=[s.letters[j],s.letters[i]]}drag=null;selection=[];render();message('Same letters. Fresh perspective!')}
function hint(){if(mode==='classic'&&s.letters.length<5)return;if(revealHint()){drag=null;clear();render();message('Follow the numbered tiles. Tap hint to reveal more.')}else message(s.hint?'Your full clue is already showing.':'No hints left this run.')}
function pointerPoint(e){const r=$('wheel').getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function pointerHit(e){return BloomTrace.hit(pointerPoint(e),positions,($('wheel').querySelector('.letter')?.offsetWidth||50)/2+3)}
function pointerStart(e){if(drag||s.over||e.button>0)return;const b=e.target.closest('.letter');if(!b)return;e.preventDefault();const i=Number(b.dataset.index);drag={id:e.pointerId,start:i,before:[...selection],startedAt:Date.now(),x:e.clientX,y:e.clientY,moved:false,last:i,cursor:pointerPoint(e)};selection=[i];drawSelection();$('wheel').setPointerCapture(e.pointerId)}
function pointerMove(e){if(!drag||e.pointerId!==drag.id)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>8)drag.moved=true;drag.cursor=pointerPoint(e);const i=pointerHit(e);if(i>=0&&i!==drag.last)select(i);drag.last=i;drawSelection()}
function pointerEnd(e){if(!drag||drag.id!==e.pointerId)return;const d=drag,hit=pointerHit(e);drag=null;if(!d.moved&&Date.now()-d.startedAt<220&&hit===d.start){selection=BloomTrace.follow(d.before,d.start,true);drawSelection();return}try{if(hit>=0&&selection.length===s.letters.length)submit();else message('Swipe cleared. Start a fresh word.')}finally{clear()}}
function pointerCancel(){drag=null;clear()}
function dialog(title,body,buttons){lastFocus=document.activeElement;drag=null;clear();$('app').inert=true;$('modal').innerHTML='<h2 id="modal-title">'+title+'</h2><div class="dialog-body">'+body+'</div>'+buttons.map((b,i)=>`<button class="dialog-btn ${i?'secondary':''}" data-dialog="${i}">${b.text}</button>`).join('');$('overlay').classList.remove('hidden');document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=buttons[Number(b.dataset.dialog)].action);$('modal').querySelector('button')?.focus()}
function closeDialog(){$('app').inert=false;$('overlay').classList.add('hidden');lastFocus?.focus()}
let audioContext;
function sound(good){if(!profile.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.frequency.setValueAtTime(good?520:180,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(good?850:100,audioContext.currentTime+.13);g.gain.setValueAtTime(.055,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.2);o.start();o.stop(audioContext.currentTime+.2)}catch{}}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<20;i++){const e=document.createElement('i');e.className='confetti';e.style.cssText=`left:${20+Math.random()*60}%;background:${['#ffda4a','#ff76bd','#5bedd6','#a291ff'][i%4]};--dx:${(Math.random()-.5)*320}px;animation-delay:${Math.random()*.2}s`;document.body.append(e);setTimeout(()=>e.remove(),1100)}}
$('back').onclick=()=>{if(s)persist();home()};$('settings').onclick=()=>dialog('Your game, your way',`<p>Use every tile once. Swipe to connect, trace backwards to undo. Release away from a letter to cancel. Three wrong words end the run.</p><p>Classic: endless growth. Adventure: finish each level’s goals. Daily: grow from 3 to 6 letters.</p><p>Shuffle unlocks at 4 letters. Classic hints unlock at 5; Adventure and Daily start with hints.</p>`,[{text:'Sound: '+(profile.sound?'ON':'OFF'),action:()=>{profile.sound=!profile.sound;persist();closeDialog();$('settings').click()}},{text:'Done',action:closeDialog}]);document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>({home,adventure,rewards}[b.dataset.page])());
document.addEventListener('keydown',e=>{if(!$('overlay').classList.contains('hidden')){if(e.key==='Escape')closeDialog();if(e.key==='Tab'){const b=[...$('modal').querySelectorAll('button')],first=b[0],last=b.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(page!=='game'||s.over)return;if(e.key==='Enter'){e.preventDefault();submit()}else if(e.key==='Backspace'){e.preventDefault();selection.pop();drawSelection()}else if(e.key==='Escape')clear();else if(/^[a-z]$/i.test(e.key)){const i=s.letters.findIndex((c,j)=>c===e.key.toUpperCase()&&!selection.includes(j));if(i>=0)select(i)}});
window.addEventListener('resize',()=>{pointerCancel();drawWheel()});window.addEventListener('blur',pointerCancel);document.addEventListener('visibilitychange',()=>{if(document.hidden)pointerCancel()});home();
